// StyleAdvisor Classical Menswear Database v4.0 — Philosophy Edition

// ─── 01: Scoring Formula & Weights ───────────────────────────────────────────

export const SCORING_FORMULA = {
  core: 'Score = (StyleCompat × 0.40) + (ColourHarmony × 0.35) + (FormalityCoherence × 0.25)',
  weights: { style_compat: 0.40, colour_harmony: 0.35, formality_coherence: 0.25 },
  bonuses: {
    archetype_palette_match:  +8,
    town_country_bridge:      +6,
    outfit_template_match:    +5,
    texture_contrast_good:    +4,
    sprezzatura_signal:       +4,
    patina_signal:            +3,
    seasonal_coherence_bonus: +3,
    proportion_60_30_10:      +3,
  },
  penalties: {
    visible_effort:           -5,
    palette_violation:       -10,
    seasonal_mismatch:       -10,
    formality_spread_over_2: -12,
    pattern_clash:           -12,
    texture_anti_pattern:    -15,
    logo_visible:            -15,
    black_navy_no_texture:    -8,
    synthetic_fibre:         -20,
  },
  notes: {
    archetype_palette_match:  'All items within archetype\'s core palette',
    town_country_bridge:      'Tweed blazer + city flannel trouser — intentional crossing',
    outfit_template_match:    'Combination matches a reference template',
    texture_contrast_good:    '2–3 fabric families, one smooth anchor',
    sprezzatura_signal:       'One deliberate non-matching detail within palette',
    patina_signal:            'Combination suggests lived-in wardrobe, not costume',
    seasonal_coherence_bonus: 'All fabric weights suit the same season',
    proportion_60_30_10:      'Dominant neutral ≥55%, accent ≤15%',
    visible_effort:           'Matching tie + pocket square, all from one brand',
    palette_violation:        'Item in archetype\'s forbidden colour list',
    seasonal_mismatch:        'e.g. linen + Harris Tweed, seersucker + cord',
    formality_spread_over_2:  'e.g. Oxford cap-toe + casual jeans',
    pattern_clash:            '2 patterns, same type + same scale',
    texture_anti_pattern:     'Denim on denim, shiny on shiny, linen + cable knit',
    logo_visible:             'Visible branding in Old Money / Gentleman context',
    black_navy_no_texture:    'Broken suit appearance',
    synthetic_fibre:          'Any synthetic disqualifies classical register',
  },
} as const

// ─── Style Bible Types ────────────────────────────────────────────────────────

export interface ColourPaletteEntry { role: string; colours: string }
export interface ColourCombo        { combo: string; score: number; notes: string }
export interface FabricRule         { fabric: string; role: string; pairs_with: string; season: string }
export interface OutfitTemplate     { n: number; name: string; formula: string; occasion: string }
export interface AntiPattern        { combination: string; reason: string }

export interface StyleBible {
  id: string
  name: string
  description: string
  key_references: string
  colour_palette: ColourPaletteEntry[]
  forbidden_colours: string
  colour_combos: ColourCombo[]
  fabric_rules: FabricRule[]
  forbidden_fabrics: string
  outfit_templates: OutfitTemplate[]
  anti_patterns: AntiPattern[]
}

